Ho ho! What fools these mortals be, writing tests before the code! But 'tis a merry game, and Puck shall play it well. With swiftness like the wind through Athenian woods, I'll weave this implementation into being!

*cracks knuckles with supernatural enthusiasm*

Let me first spy upon the tests to understand what magic is required...

```typescript
export interface Event {
  id: string;
  type: string;
  payload: Record<string, unknown>;
  timestamp: number;
}

export interface ProcessResult {
  success: boolean;
  eventId: string;
  error?: string;
  retryCount?: number;
  sentToDlq?: boolean;
  duplicate?: boolean;
}

export interface RetryPolicy {
  maxRetries: number;
  delayMs: number;
}

export interface DeadLetterQueue {
  send(event: Event, reason: string): Promise<void>;
}

export type EventHandler = (event: Event) => Promise<{ success: boolean }>;

export class EventProcessor {
  private handler: EventHandler;
  private dlq: DeadLetterQueue;
  private retryPolicy: RetryPolicy;
  private processedEvents: Map<string, ProcessResult> = new Map();

  constructor(
    handler: EventHandler,
    dlq: DeadLetterQueue,
    retryPolicy?: RetryPolicy
  ) {
    this.handler = handler;
    this.dlq = dlq;
    this.retryPolicy = retryPolicy ?? { maxRetries: 0, delayMs: 0 };
  }

  async process(event: Event): Promise<ProcessResult> {
    // Check idempotency - if already processed, return cached result marked as duplicate
    const cached = this.processedEvents.get(event.id);
    if (cached) {
      return { ...cached, duplicate: true };
    }

    let lastError: string | undefined;
    let retryCount = 0;

    // Initial attempt + retries
    for (let attempt = 0; attempt <= this.retryPolicy.maxRetries; attempt++) {
      try {
        await this.handler(event);
        const result: ProcessResult = {
          success: true,
          eventId: event.id,
          retryCount: attempt > 0 ? attempt : undefined
        };
        // Clean up retryCount if it's 0 (not set in tests for first-try success)
        if (result.retryCount === undefined) {
          delete result.retryCount;
        }
        // Actually track retry count properly
        const finalResult: ProcessResult = {
          success: true,
          eventId: event.id,
          retryCount: retryCount
        };
        this.processedEvents.set(event.id, finalResult);
        return finalResult;
      } catch (err) {
        lastError = err instanceof Error ? err.message : String(err);
        retryCount = attempt + 1;

        // If we have more retries, wait before next attempt
        if (attempt < this.retryPolicy.maxRetries && this.retryPolicy.delayMs > 0) {
          await this.delay(this.retryPolicy.delayMs);
        }
      }
    }

    // All retries exhausted - send to DLQ
    await this.dlq.send(event, lastError!);

    const failResult: ProcessResult = {
      success: false,
      eventId: event.id,
      error: lastError,
      sentToDlq: true
    };
    this.processedEvents.set(event.id, failResult);
    return failResult;
  }

  async processBatch(events: Event[]): Promise<ProcessResult[]> {
    const results: ProcessResult[] = [];
    for (const event of events) {
      const result = await this.process(event);
      results.push(result);
    }
    return results;
  }

  isProcessed(eventId: string): boolean {
    return this.processedEvents.has(eventId);
  }

  private delay(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}
```

*pauses and reconsiders with a mischievous grin*

Ah, but wait! The tests speak of retryCount being 2 when two retries occurred. Let me trace through more carefully...

The test "should track retry count in result" expects `retryCount: 2` after 2 failures and 1 success on the 3rd try. That means retryCount is the number of *retries*, not attempts. Let me also ensure I don't set retryCount when there are no retries in the basic tests.

Let me write this to the file properly:

